const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto('http://localhost:3002');
  await page.locator('#startBtn').click();
  for (const [key, ms] of [['d', 700], ['s', 350]]) { await page.keyboard.down(key); await page.waitForTimeout(ms); await page.keyboard.up(key); }
  await page.waitForTimeout(100);
  if (!await page.locator('#quizOverlay').isVisible()) throw new Error('Expected notebook quiz to open');
  const equation = await page.locator('#equation').textContent();
  const answer = await page.evaluate(() => {
    const [a, op, b] = document.querySelector('#equation').textContent.split(' ');
    return String(({ '+': (x,y)=>x+y, '−': (x,y)=>x-y, '×': (x,y)=>x*y, '÷': (x,y)=>x/y })[op](Number(a), Number(b)));
  });
  await page.locator('#answerInput').fill(answer);
  await page.locator('#answerForm button[type=submit]').click();
  await page.waitForTimeout(150);
  const count = await page.locator('#bookCount').textContent();
  if (count !== '1 / 7') throw new Error(`Expected notebook count 1 / 7, got ${count}`);
  await page.locator('#restartBtn').click();
  const resetCount = await page.locator('#bookCount').textContent();
  if (resetCount !== '0 / 7') throw new Error(`Restart failed: ${resetCount}`);
  await browser.close();
  console.log(JSON.stringify({ equation, answered: answer, count, resetCount, errors }));
  if (errors.length) process.exitCode = 1;
})();
